"""Validation-only complete-record replay; never changes canonical comparators."""
import copy
import hashlib
import json
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/'tools'))
import conformance as c


def strict_json(text):
    def unique(pairs):
        result={}
        for k,v in pairs:
            if k in result:raise ValueError('Duplicate JSON field')
            result[k]=v
        return result
    return json.loads(text,object_pairs_hook=unique,parse_constant=lambda value:(_ for _ in ()).throw(ValueError('Nonfinite JSON')))


def strict(text,cases):
    lines=text.splitlines()
    if len(lines)!=len(cases) or any(not line.strip() for line in lines):raise ValueError('Complete framing differs')
    rows=[strict_json(line) for line in lines]
    for row,case in zip(rows,cases):
        keys={'id','width','height','pixels'}
        if case.get('export_qoi'):keys.add('qoi')
        if 'palette' in case:keys.update(('palette','palette_count'))
        if 'alpha_border' in case:keys.add('alpha_border')
        if type(row) is not dict or row.keys()!=keys:raise ValueError('Exact schema differs')
        if type(row['id']) is not str or any(type(row[k]) is not int for k in ('width','height')):raise ValueError('Metadata type differs')
        if 'palette_count' in row and type(row['palette_count']) is not int:raise ValueError('Palette type differs')
        for field in ('pixels','qoi','palette','alpha_border'):
            if field in row and (type(row[field]) is not list or any(type(v) is not int for v in row[field])):raise ValueError('Array type differs')
    # Retain the canonical domain checks unchanged, then compare entire records.
    c.parse_output(text,cases)
    return rows


def compare_full(reference,actual):
    if reference!=actual:raise ValueError("Complete records differ")


def main():
    build=ROOT/'.build';cases=json.loads((build/'scenarios.json').read_text());report=json.loads((build/'conformance.json').read_text())
    if report.get('passed') is not True:raise ValueError('Canonical run did not pass')
    if report['sources'] != c.source_gate(): raise ValueError('Integrated source identity differs')
    for name,digest in report['verification_sources'].items():
        if hashlib.sha256((ROOT/name).read_bytes()).hexdigest() != digest: raise ValueError('Verification source drift: '+name)
    reference=strict((build/'reference.jsonl').read_text(),cases)
    counts=dict(scenarios=len(reference),words=sum(len(r['pixels']) for r in reference),qoi_bytes=sum(len(r.get('qoi',[])) for r in reference),palette_words=sum(len(r.get('palette',[])) for r in reference))
    if counts!=dict(scenarios=261,words=40101,qoi_bytes=333,palette_words=23):raise ValueError('Canonical coverage changed')
    # A changed optional field, boolean integer, duplicate field, blank line,
    # extra field, missing row or row order must fail this validator.
    text=(build/'reference.jsonl').read_text();bad=[]
    rows=copy.deepcopy(reference);rows[0]['width']=True;bad.append('\n'.join(map(json.dumps,rows)))
    rows=copy.deepcopy(reference);rows[0]['extra']=1;bad.append('\n'.join(map(json.dumps,rows)))
    rows=reference[1:]+reference[:1];bad.append('\n'.join(map(json.dumps,rows)))
    bad += [text+'\n', '\n'.join(text.splitlines()[1:]),text.replace('"width":','"width":1,"width":',1)]
    for wrong in bad:
        try:strict(wrong,cases)
        except (ValueError,KeyError):pass
        else:raise ValueError('Strict framing negative control accepted')
    optional=[]
    for field in ('qoi','palette','alpha_border'):
        rows=copy.deepcopy(reference);index=next(i for i,row in enumerate(rows) if field in row)
        if field=='alpha_border':
            row=rows[index];row[field]=[0,0,0,0] if row[field]!=[0,0,0,0] else [0,0,row['width'],row['height']]
        else:rows[index][field][0]^=1
        # Mutants remain well-typed/in-domain, so only complete-value comparison
        # can reject this otherwise valid framing. No mutated assets run native.
        actual=strict('\n'.join(map(json.dumps,rows)),cases)
        try:compare_full(reference,actual)
        except ValueError:optional.append(field)
        else:raise ValueError('Optional field mismatch escaped: '+field)
    lanes={}
    for lane in ('cpu-1','cpu-2','javascript'):
        path=build/(lane+'.jsonl');actual=strict(path.read_text(),cases)
        compare_full(reference,actual)
        lanes[lane]=dict(passed=True,sha256=hashlib.sha256(path.read_bytes()).hexdigest(),**counts)
    artifacts={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [Path(__file__),build/'reference.jsonl',build/'scenarios.json',build/'conformance.json']}
    result=dict(passed=True,scope='validation-only strict complete-record replay',sources=c.source_gate(),artifacts=artifacts,lanes=lanes,negative_controls=len(bad)+len(optional),optional_field_mutants=optional)
    (build/'tga-integration-verification/strict-replay-final.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(dict(passed=True,lanes=lanes,negative_controls=len(bad)+len(optional),optional_field_mutants=optional)))


if __name__=='__main__':main()

.build/integration-validation/independen.text:
"""Independent read-only complete-record canonical replay and fresh receipt audit."""
import copy
import hashlib
import json
import re
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
OUT=Path(__file__).parent
BUILD=ROOT/'.build'

def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def strict_json(text):
    def unique(pairs):
        result={}
        for key,value in pairs:
            if key in result:raise ValueError('Duplicate JSON key')
            result[key]=value
        return result
    def invalid(value):raise ValueError('Nonfinite JSON number')
    return json.loads(text,object_pairs_hook=unique,parse_constant=invalid)

def rows(text,cases):
    lines=text.splitlines()
    if len(lines)!=len(cases) or any(not line.strip() for line in lines):
        raise ValueError('Incomplete or extra canonical record')
    result=[]
    for line,case in zip(lines,cases):
        row=strict_json(line)
        keys={'id','width','height','pixels'}
        if case.get('export_qoi'):keys.add('qoi')
        if 'palette' in case:keys.update(('palette','palette_count'))
        if 'alpha_border' in case:keys.add('alpha_border')
        if type(row) is not dict or row.keys()!=keys:raise ValueError('Wrong schema')
        if type(row['id']) is not str or row['id']!=case['id']:raise ValueError('Wrong record identity or order')
        if any(type(row[k]) is not int or row[k]<=0 for k in ('width','height')):raise ValueError('Wrong dimensions')
        if 'palette_count' in row and (type(row['palette_count']) is not int or row['palette_count']<0):raise ValueError('Wrong palette count')
        for key in ('pixels','palette','qoi','alpha_border'):
            if key in row and (type(row[key]) is not list or any(type(v) is not int for v in row[key])):raise ValueError('Wrong array type')
        if len(row['pixels'])!=row['width']*row['height']:raise ValueError('Wrong pixel length')
        if any(not 0<=v<=4294967295 for v in row['pixels']+row.get('palette',[])):raise ValueError('Wrong word domain')
        if any(not 0<=v<=255 for v in row.get('qoi',[])):raise ValueError('Wrong byte domain')
        if 'alpha_border' in row and len(row['alpha_border'])!=4:raise ValueError('Wrong border length')
        result.append(row)
    return result

def main():
    report=strict_json((BUILD/'conformance.json').read_text())
    serial=strict_json((BUILD/'tga-integration-verification/serial.json').read_text())
    replay=strict_json((BUILD/'tga-integration-verification/strict-replay-final.json').read_text())
    assert report['passed'] is serial['passed'] is replay['passed'] is True
    assert serial['base_revision']=='0c663c9a85a8560199ccef89f76251ea05cfce8b'
    assert report['sources']==serial['sources']==replay['sources']
    assert report['sources']['jonlib.bend']=='83e59ebeb22bd4b104399ef8824f3fd53719e7009b661e123190dfe05ba3dc8a'
    for name,digest in report['sources'].items():assert sha(ROOT/name)==digest, name
    for name,digest in report['verification_sources'].items():assert sha(ROOT/name)==digest, name
    for name,digest in report['reference_artifacts'].items():assert sha(BUILD/name)==digest, name
    assert report['toolchain']==strict_json((ROOT/'toolchain.json').read_text())
    assert report['proof']=='All terms check.' and serial['proof_laws']==149
    assert report['reference_environment']['policy']=='clean-loader'
    assert all(v is None for v in report['reference_environment']['effective_child_loader'].values())
    assert (BUILD/'tga-integration-verification/proof.stdout').read_text().strip()=='All terms check.'
    suite=(BUILD/'tga-integration-verification/python-suite.stderr').read_text()
    assert re.search(r'Ran 585 tests in [0-9.]+s\n\nOK\s*$',suite)
    assert not re.search(r'\.\.\. skipped|expected failure|unexpected success',suite)
    labels=['python-suite','proof','syntax','project','api-drift','diff-check','focused-tga','focused-pnm-file',
            'canonical-native-configure','canonical-native-build','canonical','strict-canonical']
    assert [r['label'] for r in serial['runs']]==labels
    for run in serial['runs']:
        assert type(run['exit_code']) is int and run['exit_code']==0
        assert run['error'] is None and run['process_group_cleanup'] is True
        for name,digest in run['artifacts'].items():assert sha(ROOT/name)==digest, name
    for name,digest in serial['canonical_native_artifacts'].items():assert sha(ROOT/name)==digest, name
    cache=(BUILD/'raylib/CMakeCache.txt').read_text()
    fields=dict(re.findall(r'^([A-Za-z_][A-Za-z0-9_]*):[^=\n]+=(.*)$',cache,re.M))
    flags=(BUILD/'raylib/raylib/CMakeFiles/raylib.dir/flags.make').read_text().split()
    for key in ('SUPPORT_FILEFORMAT_TGA','SUPPORT_FILEFORMAT_PNM'):
        assert fields[key]=='ON'
        definitions=[v for v in flags if v.startswith(('-D'+key,'-U'+key))]
        assert definitions in (['-D'+key],['-D'+key+'=1'])
    assert fields['PLATFORM']=='Memory' and fields['CMAKE_BUILD_TYPE']=='Release' and fields['CUSTOMIZE_BUILD']=='ON'
    assert '-DEXTERNAL_CONFIG_FLAGS' in flags and '-DPLATFORM_MEMORY' in flags
    cases=strict_json((BUILD/'scenarios.json').read_text())
    reference_text=(BUILD/'reference.jsonl').read_text()
    reference=rows(reference_text,cases)
    counts={'scenarios':len(reference),'words':sum(len(r['pixels']) for r in reference),
            'qoi_bytes':sum(len(r.get('qoi',[])) for r in reference),'palette_words':sum(len(r.get('palette',[])) for r in reference)}
    assert counts=={'scenarios':261,'words':40101,'qoi_bytes':333,'palette_words':23}
    lanes={}
    for lane in ('cpu-1','cpu-2','javascript'):
        assert rows((BUILD/(lane+'.jsonl')).read_text(),cases)==reference
        assert report['lanes'][lane]=={'passed':True,'scenarios':261,'pixels':40101}
        assert sha(BUILD/(lane+'.jsonl'))==replay['lanes'][lane]['sha256']
        lanes[lane]={'passed':True,**counts,'sha256':sha(BUILD/(lane+'.jsonl'))}
    assert len(report['candidate_batches'])==17
    cursor=0
    for batch in report['candidate_batches']:
        assert batch['start']==cursor and batch['phase']=='complete'
        cursor+=batch['scenarios']
    assert cursor==261
    for key in ('contracts','transform_contracts','decode_contracts'):assert report[key]==['cpu','javascript']
    for key in ('example','composite_example','transform_example','qoi_file_roundtrip'):assert report[key]['passed'] is True
    bad=[]
    for key,value in [('width',True),('extra',1)]:
        mutant=copy.deepcopy(reference);mutant[0][key]=value;bad.append('\n'.join(map(json.dumps,mutant)))
    bad += ['\n'.join(map(json.dumps,reference[1:]+reference[:1])),reference_text+'\n',
            '\n'.join(reference_text.splitlines()[1:]),reference_text.replace('"width":','"width":1,"width":',1)]
    for text in bad:
        try:rows(text,cases)
        except ValueError:pass
        else:raise ValueError('Negative parser control accepted')
    for field in ('qoi','palette','alpha_border'):
        mutant=copy.deepcopy(reference);i=next(i for i,r in enumerate(mutant) if field in r)
        mutant[i][field][0]^=1
        assert rows('\n'.join(map(json.dumps,mutant)),cases)!=reference
    assert replay['negative_controls']==9 and replay['optional_field_mutants']==['qoi','palette','alpha_border']
    result={'passed':True,'scope':'Fresh combined source canonical and strict full-record verification; no native rerun',
            'sources':report['sources'],'lanes':lanes,'independent_negative_controls':9,
            'proof_laws':149,'python_tests':585,'fresh_tga_and_pnm_enabled_native_archive':serial['canonical_native_artifacts'],
            'artifacts':{str(p.relative_to(ROOT)):sha(p) for p in (Path(__file__),BUILD/'conformance.json',
             BUILD/'tga-integration-verification/serial.json',BUILD/'tga-integration-verification/strict-replay-final.json')}}
    (OUT/'independent-canonical-evidence-audit.json').write_text(json.dumps(result,indent=2)+'\n')
    print(json.dumps({'passed':True,'lanes':lanes,'negative_controls':9,'laws':149,'python_tests':585},indent=2))

if __name__=='__main__':main()
